package org.cleanyourtv.homebridge;
import android.content.*;import android.database.*;import android.net.Uri;import org.json.*;
public class ShortcutProvider extends ContentProvider{
 public boolean onCreate(){return true;}
 public Cursor query(Uri u,String[] projection,String selection,String[] args,String sort){String[] pkgs=getContext().getPackageManager().getPackagesForUid(android.os.Binder.getCallingUid());if(android.os.Binder.getCallingUid()!=0&&(pkgs==null||!java.util.Arrays.asList(pkgs).contains("com.gathin.tvhome")))throw new SecurityException("仅限 Aurora Launcher");long identity=android.os.Binder.clearCallingIdentity();try{MatrixCursor c=new MatrixCursor(new String[]{"key","package","id","label"});JSONArray a=ShortcutStore.records(getContext());for(int i=0;i<a.length();i++)try{JSONObject s=a.getJSONObject(i);c.addRow(new Object[]{s.getString("key"),s.getString("package"),s.getString("id"),s.getString("label")});}catch(Exception ignored){}return c;}finally{android.os.Binder.restoreCallingIdentity(identity);}}
 public android.os.ParcelFileDescriptor openFile(Uri u,String mode)throws java.io.FileNotFoundException{
  checkCaller();if(!"r".equals(mode))throw new SecurityException();long token=android.os.Binder.clearCallingIdentity();
  try{String key=u.getLastPathSegment();JSONArray a=ShortcutStore.records(getContext());for(int i=0;i<a.length();i++){JSONObject item=a.getJSONObject(i);if(!key.equals(item.getString("key")))continue;
   android.content.pm.LauncherApps apps=getContext().getSystemService(android.content.pm.LauncherApps.class);
   java.util.List<android.content.pm.ShortcutInfo> list=apps.getShortcuts(new android.content.pm.LauncherApps.ShortcutQuery().setPackage(item.getString("package")).setShortcutIds(java.util.Collections.singletonList(item.getString("id"))).setQueryFlags(android.content.pm.LauncherApps.ShortcutQuery.FLAG_MATCH_PINNED),android.os.Process.myUserHandle());
   if(list==null||list.isEmpty())break;android.graphics.drawable.Drawable d=apps.getShortcutIconDrawable(list.get(0),256);if(d==null)break;
   android.graphics.Bitmap b=android.graphics.Bitmap.createBitmap(256,256,android.graphics.Bitmap.Config.ARGB_8888);d.setBounds(0,0,256,256);d.draw(new android.graphics.Canvas(b));
   java.io.File f=new java.io.File(getContext().getCacheDir(),key+".png");try(java.io.FileOutputStream out=new java.io.FileOutputStream(f)){b.compress(android.graphics.Bitmap.CompressFormat.PNG,100,out);}b.recycle();return android.os.ParcelFileDescriptor.open(f,android.os.ParcelFileDescriptor.MODE_READ_ONLY);
  }}catch(Exception e){android.util.Log.w("AuroraShortcut","Icon unavailable",e);}finally{android.os.Binder.restoreCallingIdentity(token);}throw new java.io.FileNotFoundException();
 }
 private void checkCaller(){String[] p=getContext().getPackageManager().getPackagesForUid(android.os.Binder.getCallingUid());if(android.os.Binder.getCallingUid()!=0&&(p==null||!java.util.Arrays.asList(p).contains("com.gathin.tvhome")))throw new SecurityException();}
 public int delete(Uri u,String selection,String[] args){checkCaller();long token=android.os.Binder.clearCallingIdentity();try{String key=u.getLastPathSegment();JSONArray a=ShortcutStore.records(getContext()),next=new JSONArray();String pkg=null;for(int i=0;i<a.length();i++){JSONObject v=a.getJSONObject(i);if(key.equals(v.getString("key")))pkg=v.getString("package");else next.put(v);}if(pkg==null)return 0;java.util.List<String> ids=new java.util.ArrayList<>();for(int i=0;i<next.length();i++)if(pkg.equals(next.getJSONObject(i).getString("package")))ids.add(next.getJSONObject(i).getString("id"));getContext().getSystemService(android.content.pm.LauncherApps.class).pinShortcuts(pkg,ids,android.os.Process.myUserHandle());getContext().getSharedPreferences("shortcuts",0).edit().putString("items",next.toString()).commit();return 1;}catch(Exception e){throw new IllegalStateException(e);}finally{android.os.Binder.restoreCallingIdentity(token);}}
 public String getType(Uri u){return "vnd.android.cursor.dir/aurora-shortcuts";}
 public Uri insert(Uri u,ContentValues v){throw new SecurityException();}public int update(Uri u,ContentValues v,String s,String[]a){throw new SecurityException();}
}
